/**
 * Stateful entry point for the pushed `stockAnalysis/{symbol}` destination. Only `DetailHeader`
 * and the pill tab bar are pinned now -- `TechnicalRead` and the HIGH-urgency alert moved into the
 * scrollable tab content (see `StockDetailScreen`) so they don't permanently eat into the tabs'
 * share of the screen. `StockDetailScreen` (the selected tab's content) sits inside the
 * pull-to-refresh area, so pulling down works from any tab but never disturbs the pinned zone
 * above it. `Modifier.windowInsetsPadding(WindowInsets.statusBars)` handles the status-bar inset
 * directly -- this route has no Material `TopAppBar` to lean on for that (see `MainActivity`'s
 * `isPushedDestination`, which excludes this route from the global collapsing top bar entirely).
 * The floating bottom nav is hidden here too (same `isPushedDestination` check) -- only the pinned
 * zone and tab bar act as this screen's chrome.
 */
@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun StockDetailRoute(
    scaffoldPadding: PaddingValues,
    onNavigateUp: () -> Unit,
    onNavigateToWebView: (String) -> Unit,
    viewModel: StockDetailViewModel = hiltViewModel()
) {
    val uiState by viewModel.uiState.collectAsStateWithLifecycle()
    val snackbarHostState = remember { SnackbarHostState() }
    val pullRefreshState = rememberPullToRefreshState()
    val lifecycleOwner = LocalLifecycleOwner.current

    DisposableEffect(lifecycleOwner) {
        val observer = LifecycleEventObserver { _, event ->
            when (event) {
                Lifecycle.Event.ON_START -> viewModel.onStart()
                Lifecycle.Event.ON_STOP -> viewModel.onStop()
                else -> {}
            }
        }
        lifecycleOwner.lifecycle.addObserver(observer)
        onDispose {
            lifecycleOwner.lifecycle.removeObserver(observer)
        }
    }

    LaunchedEffect(uiState.error) {
        uiState.error?.message?.let { message ->
            snackbarHostState.showSnackbar(message)
            viewModel.clearError()
        }
    }

    Column(
        modifier = Modifier
            .fillMaxSize()
            .windowInsetsPadding(WindowInsets.statusBars)
    ) {
        DetailHeader(
            symbol = uiState.symbol,
            name = uiState.preview?.name,
            price = uiState.preview?.price,
            changePercent = uiState.preview?.changePercent,
            technicalSetup = uiState.preview?.technicalSetup,
            regimeAtAnalysis = uiState.preview?.regimeAtAnalysis,
            analyzedAsOfTimestamp = uiState.detail?.timestamp,
            onNavigateUp = onNavigateUp,
            modifier = Modifier.fillMaxWidth()
        )

        DetailPillTabRow(
            selectedTabIndex = uiState.selectedTabIndex,
            onTabSelected = viewModel::onTabSelected
        )

        Box(modifier = Modifier.fillMaxSize()) {
            PullToRefreshBox(
                isRefreshing = uiState.isRefreshing,
                onRefresh = { viewModel.refresh() },
                state = pullRefreshState,
                indicator = {
                    Indicator(
                        modifier = Modifier.align(Alignment.TopCenter),
                        isRefreshing = uiState.isRefreshing,
                        state = pullRefreshState
                    )
                }
            ) {
                when {
                    uiState.detail != null -> {
                        StockDetailScreen(
                            detail = uiState.detail,
                            preview = uiState.preview,
                            selectedTabIndex = uiState.selectedTabIndex,
                            expandedChipIds = uiState.expandedChipIds,
                            expandedNewsIds = uiState.expandedNewsIds,
                            onToggleChip = viewModel::toggleChipExpanded,
                            onToggleNews = viewModel::toggleNewsExpanded,
                            onArticleClick = onNavigateToWebView,
                            scaffoldPadding = scaffoldPadding
                        )
                    }

                    uiState.isLoading -> {
                        Box(modifier = Modifier.fillMaxSize(), contentAlignment = Alignment.Center) {
                            CircularProgressIndicator()
                        }
                    }

                    uiState.error != null -> {
                        StockAnalysisErrorState(error = uiState.error!!, onRetry = { viewModel.refresh() })
                    }

                    // Defensive fallback only -- `detail`/`isLoading`/`error` in practice always
                    // cover the real states (the ViewModel starts `isLoading = true` and a fetch
                    // is always in flight by the time this composes).
                    else -> {
                        Box(modifier = Modifier.fillMaxSize(), contentAlignment = Alignment.Center) {
                            CircularProgressIndicator()
                        }
                    }
                }
            }

            SnackbarHost(
                hostState = snackbarHostState,
                modifier = Modifier
                    .align(Alignment.BottomCenter)
                    .padding(bottom = scaffoldPadding.calculateBottomPadding())
            )
        }
    }
}

/**
 * A horizontally-scrolling row of tab chips -- replaces an earlier `PrimaryTabRow` pass with a
 * segmented-control look instead of Material's underline-indicator style. The selected chip is a
 * solid `accentPrimary` fill (`accentOn` text, the token this app already uses for text-on-accent-
 * background elsewhere); unselected chips are outlined (`accentSurfaceBorder` hairline, same
 * border token `OutlinedBadge` uses) with muted text. `horizontalScroll` rather than a fixed-width
 * `Row` since chip width now follows each label's own content instead of splitting the row into 4
 * equal columns -- "Technicals" is a good deal wider than "Read", and forcing them to match would
 * either clip the long label or waste space around the short ones.
 *
 * 💡 `corner_radius_small`, not the fully-rounded `corner_radius_pill` -- these chips used to be
 * pill-shaped, the exact same shape `DetailHeader`'s `technicalSetup` `OutlinedBadge` sits right
 * above them, and having both use one shape made the tab row read as one more badge in that
 * cluster rather than the screen's own navigation. A softer rounded-rectangle keeps it visually
 * distinct from the pinned header's pills above it.
 */
@Composable
private fun DetailPillTabRow(
    selectedTabIndex: Int,
    onTabSelected: (Int) -> Unit,
    modifier: Modifier = Modifier
) {
    val pulseColors = LocalPulseColors.current

    Row(
        modifier = modifier
            .fillMaxWidth()
            .horizontalScroll(rememberScrollState())
            .padding(
                horizontal = dimensionResource(id = R.dimen.padding_large),
                vertical = dimensionResource(id = R.dimen.padding_medium)
            ),
        horizontalArrangement = androidx.compose.foundation.layout.Arrangement.spacedBy(dimensionResource(id = R.dimen.padding_small))
    ) {
        DetailTab.entries.forEachIndexed { index, tab ->
            val isSelected = index == selectedTabIndex
            Surface(
                color = if (isSelected) pulseColors.accentPrimary else MaterialTheme.colorScheme.background,
                border = if (isSelected) null else BorderStroke(dimensionResource(id = R.dimen.border_thin), pulseColors.accentSurfaceBorder),
                shape = RoundedCornerShape(dimensionResource(id = R.dimen.corner_radius_small)),
                modifier = Modifier.clickable { onTabSelected(index) }
            ) {
                Text(
                    text = stringResource(id = tab.labelRes),
                    style = MaterialTheme.typography.labelMedium.copy(fontWeight = FontWeight.Bold),
                    color = if (isSelected) pulseColors.accentOn else pulseColors.onSurfaceMuted,
                    modifier = Modifier.padding(
                        horizontal = dimensionResource(id = R.dimen.padding_large),
                        vertical = dimensionResource(id = R.dimen.padding_medium)
                    )
                )
            }
        }
    }
}
